INSERT INTO "Questions" ("Id", "CategoryId", "Title", "Difficulty", "Content") VALUES
(69, 6, 'This program has a projected start date of January 2027 in our office here in Christchurch. Are you available to start at that time?', 'Easy', '[Trimble interview] This program has a projected start date of January 2027 in our office here in Christchurch. Are you available to start at that time?'),
(70, 6, 'Are you legally eligible to work in New Zealand?', 'Easy', '[Trimble interview] Are you legally eligible to work in New Zealand?'),
(71, 6, 'What are your salary expectations for the role?', 'Easy', '[Trimble interview] What are your salary expectations for the role?'),
(72, 6, 'Do you currently have any other offers or interview deadlines that we should be aware of from a timeline perspective?', 'Easy', '[Trimble interview] Do you currently have any other offers or interview deadlines that we should be aware of from a timeline perspective?'),
(73, 6, 'Whereabouts are you based? Are you comfortable working from an office, or do you prefer hybrid?', 'Easy', '[One NZ interview] Whereabouts are you based? Are you comfortable working from an office, or do you prefer hybrid?'),
(74, 6, 'You''re full time at one company but also part time at another. How does that work? Is that a paid role as well? How do you think that plays out coming into a full-time role here?', 'Medium', '[Mercury interview] You''re full time at one company but also part time at another. How does that work? Is that a paid role as well? How do you think that plays out coming into a full-time role here?'),
(75, 6, 'I''ve got your CV, but just give me a very brief overview of your work experience or background.', 'Easy', '[Mercury interview] I''ve got your CV, but just give me a very brief overview of your work experience or background.'),
(76, 6, 'You''re currently working at both X and Y? That''s very busy. Walk me through that.', 'Medium', '[Trimble interview] You''re currently working at both X and Y? That''s very busy. Walk me through that.'),
(77, 6, 'Can you tell me about your responsibilities with [current employer]?', 'Easy', '[Trimble interview] Can you tell me about your responsibilities with [current employer]?'),
(78, 6, 'What do you enjoy about your current role?', 'Easy', '[One NZ interview] What do you enjoy about your current role?'),
(79, 6, 'Why are you looking for a new role this time?', 'Easy', '[Trimble interview] Why are you looking for a new role this time?'),
(80, 6, 'What are the key things that you''re looking for in your next role?', 'Medium', '[Mercury interview] What are the key things that you''re looking for in your next role?'),
(81, 6, 'From what you''ve read and what we''ve discussed, what do you think are the main things that would appeal to you about the role?', 'Medium', '[Mercury interview] From what you''ve read and what we''ve discussed, what do you think are the main things that would appeal to you about the role?'),
(82, 6, 'Why are you interested in the rotational program, and why do you think it''d be a good place to start or continue your career?', 'Medium', '[Trimble interview] Why are you interested in the rotational program, and why do you think it''d be a good place to start or continue your career?'),
(83, 6, 'What have you learned about the company so far, and why are you interested in working with us?', 'Medium', '[Trimble interview] What have you learned about the company so far, and why are you interested in working with us?'),
(84, 6, 'Does the role sound like it''s a good fit for you or not?', 'Easy', '[One NZ interview] Does the role sound like it''s a good fit for you or not?'),
(85, 6, 'Why are you looking to leave your current role?', 'Easy', '[Mercury interview] Why are you looking to leave your current role?'),
(86, 6, 'What excites you most about the opportunity here?', 'Medium', '[Mercury interview] What excites you most about the opportunity here?'),
(87, 6, 'Where do you think you would need development to be successful in this role?', 'Medium', '[One NZ interview] Where do you think you would need development to be successful in this role?'),
(88, 6, 'What personal qualities or skills do you think would make you a good candidate for this role?', 'Medium', '[Mercury interview] What personal qualities or skills do you think would make you a good candidate for this role?'),
(89, 6, 'How do you think other people would describe your approach to work?', 'Medium', '[Mercury interview] How do you think other people would describe your approach to work?'),
(90, 6, 'Can you give me an example of a time where you had to quickly learn a new skill or technology to meet the demands of a project? How did you go about learning it, and what was the outcome?', 'Medium', '[Trimble interview] Can you give me an example of a time where you had to quickly learn a new skill or technology to meet the demands of a project? How did you go about learning it, and what was the outcome?'),
(91, 6, 'Can you provide me an example of a time where you willingly took on a task or responsibility that stretched your skills or abilities?', 'Medium', '[Trimble interview] Can you provide me an example of a time where you willingly took on a task or responsibility that stretched your skills or abilities?'),
(92, 6, 'Can you share an example of a time where you demonstrated leadership during a group project or through work experience? How would you describe your leadership style, and how do you plan to further develop your leadership skills post graduation?', 'Hard', '[Trimble interview] Can you share an example of a time where you demonstrated leadership during a group project or through work experience? How would you describe your leadership style, and how do you plan to further develop your leadership skills post graduation?'),
(93, 6, 'Have you ever faced a situation where the data didn''t support the desired narrative or outcome? How did you handle that?', 'Medium', '[Trimble interview] Have you ever faced a situation where the data didn''t support the desired narrative or outcome? How did you handle that?'),
(94, 6, 'Can you give me an example of how you''ve dealt with a challenging stakeholder and how you overcame the situation?', 'Medium', '[One NZ interview] Can you give me an example of how you''ve dealt with a challenging stakeholder and how you overcame the situation?'),
(95, 6, 'What would you do if they get angry — angry with something you''ve done or the way you''re approaching a project?', 'Medium', '[One NZ interview] What would you do if they get angry — angry with something you''ve done or the way you''re approaching a project?'),
(96, 6, 'How do you manage your work on a day-to-day basis? How do you decide what you work on first? How do you keep track of your work?', 'Medium', '[One NZ interview] How do you manage your work on a day-to-day basis? How do you decide what you work on first? How do you keep track of your work?'),
(97, 6, 'Two stakeholders from different business units both say their job is your top priority. You can only do one. How will you decide which one you do?', 'Hard', '[One NZ interview] Two stakeholders from different business units both say their job is your top priority. You can only do one. How will you decide which one you do?'),
(98, 6, 'How do you ensure that you understand instructions or expectations when something isn''t clear?', 'Medium', '[Trimble interview] How do you ensure that you understand instructions or expectations when something isn''t clear?'),
(99, 6, 'Can you give me an example or tell me a time when you had several important things competing for your attention? How do you decide what to work on or deal with first?', 'Medium', '[Mercury interview] Can you give me an example or tell me a time when you had several important things competing for your attention? How do you decide what to work on or deal with first?'),
(100, 6, 'Can you give an example where you had to persuade someone to accept your point of view, when they had a different point of view to start off with?', 'Medium', '[Mercury interview] Can you give an example where you had to persuade someone to accept your point of view, when they had a different point of view to start off with?'),
(101, 6, 'Can you give an example where you had to deal with a problem you had never seen before? How did you approach it from the moment you became aware through to the outcome?', 'Hard', '[Mercury interview] Can you give an example where you had to deal with a problem you had never seen before? How did you approach it from the moment you became aware through to the outcome?'),
(102, 6, 'What if you can''t get all the information from the user because they''re very busy? How would you approach that?', 'Medium', '[Mercury interview] What if you can''t get all the information from the user because they''re very busy? How would you approach that?'),
(103, 6, 'Tell me about a time when something important went wrong and you were under pressure to get it resolved quickly. How did you handle that?', 'Hard', '[Mercury interview] Tell me about a time when something important went wrong and you were under pressure to get it resolved quickly. How did you handle that?'),
(104, 6, 'If you come across a system or technology you''re not familiar with, how do you make yourself confident to work independently?', 'Medium', '[Mercury interview] If you come across a system or technology you''re not familiar with, how do you make yourself confident to work independently?'),
(105, 6, 'Is contributing to documentation part of your current work? What tools do you use to manage troubleshooting guides, FAQs, runbooks?', 'Medium', '[Mercury interview] Is contributing to documentation part of your current work? What tools do you use to manage troubleshooting guides, FAQs, runbooks?'),
(106, 6, 'Can you tell me about a critical incident that you have personally handled?', 'Hard', '[Mercury interview] Can you tell me about a critical incident that you have personally handled?'),
(107, 6, 'Do you have to make runbooks for your operations? How do you make a good one?', 'Medium', '[Mercury interview] Do you have to make runbooks for your operations? How do you make a good one?'),
(108, 6, 'Can you give us a scenario where you''ve done some troubleshooting — what steps you went through to find the issue and how you corrected it?', 'Hard', '[Westpac interview] Can you give us a scenario where you''ve done some troubleshooting — what steps you went through to find the issue and how you corrected it?'),
(109, 6, 'Can you give us a scenario of some project work that you''ve done, and what your role was in relation to that?', 'Medium', '[Westpac interview] Can you give us a scenario of some project work that you''ve done, and what your role was in relation to that?'),
(110, 1, 'What''s the difference between heap memory and stack memory?', 'Medium', '[Trimble interview] What''s the difference between heap memory and stack memory?'),
(111, 1, 'What does object oriented programming mean?', 'Easy', '[Trimble interview] What does object oriented programming mean?'),
(112, 1, 'What programming languages are you the most comfortable with?', 'Easy', '[Trimble interview] What programming languages are you the most comfortable with?'),
(113, 1, 'What level of expertise do you have in Python — do you use it every day or a little bit?', 'Medium', '[One NZ interview] What level of expertise do you have in Python — do you use it every day or a little bit?'),
(114, 1, '[Screen share: a PowerShell script] Can you give us your impression of this script? There is a problem in it — can you find the issue? Any other suggestions you''d highlight?', 'Medium', '[Mercury interview] [Screen share: a PowerShell script] Can you give us your impression of this script? There is a problem in it — can you find the issue? Any other suggestions you''d highlight?'),
(115, 3, 'How would you transfer data from an S3 bucket across AWS accounts to be processed by a SageMaker endpoint — say a day''s worth of transcripts? What services would be involved?', 'Hard', '[One NZ interview] How would you transfer data from an S3 bucket across AWS accounts to be processed by a SageMaker endpoint — say a day''s worth of transcripts? What services would be involved?'),
(116, 1, 'You''ve built a function retrieving an account balance from an external system. Now you''re thinking about error handling. What are you thinking about, and what scenarios do you want to handle?', 'Medium', '[One NZ interview] You''ve built a function retrieving an account balance from an external system. Now you''re thinking about error handling. What are you thinking about, and what scenarios do you want to handle?'),
(117, 4, 'Can you think of a use case where you would build something to drive additional self-service for customers? What tooling would you use and why?', 'Medium', '[One NZ interview] Can you think of a use case where you would build something to drive additional self-service for customers? What tooling would you use and why?'),
(118, 4, 'You''re building an AI agent to retrieve data from a backend and read it back to the customer. What system components are you using, and what makes it production ready and trustworthy?', 'Hard', '[One NZ interview] You''re building an AI agent to retrieve data from a backend and read it back to the customer. What system components are you using, and what makes it production ready and trustworthy?'),
(119, 4, 'There''s an industry term called AI observability. What would you be thinking about wanting to observe for the AI agent you''ve built?', 'Hard', '[One NZ interview] There''s an industry term called AI observability. What would you be thinking about wanting to observe for the AI agent you''ve built?'),
(120, 6, 'How have you used AI in your project workflows so far?', 'Easy', '[Trimble interview] How have you used AI in your project workflows so far?'),
(121, 6, 'Where do you land on using AI-generated code? How dirty do you like getting your hands with these new AI solutions?', 'Medium', '[One NZ interview] Where do you land on using AI-generated code? How dirty do you like getting your hands with these new AI solutions?'),
(122, 3, 'I see you call out CI/CD. What kind of environments have you worked with to do that?', 'Medium', '[One NZ interview] I see you call out CI/CD. What kind of environments have you worked with to do that?'),
(123, 1, 'What''s your experience with Windows Server, IIS, anything like that?', 'Medium', '[Mercury interview] What''s your experience with Windows Server, IIS, anything like that?'),
(124, 1, 'What''s your level of SQL knowledge? Any flavour of SQL — we''re not looking for a SQL developer.', 'Medium', '[Mercury interview] What''s your level of SQL knowledge? Any flavour of SQL — we''re not looking for a SQL developer.'),
(125, 3, 'If there are two platforms, one business critical and one not critical, would you set up monitoring differently for them?', 'Hard', '[Mercury interview] If there are two platforms, one business critical and one not critical, would you set up monitoring differently for them?'),
(126, 3, 'You mentioned you mostly work on AWS. What AWS services have you worked on or supported?', 'Medium', '[Mercury interview] You mentioned you mostly work on AWS. What AWS services have you worked on or supported?'),
(127, 1, 'A Windows application keeps crashing. How do you go about figuring out what''s wrong?', 'Medium', '[Mercury interview] A Windows application keeps crashing. How do you go about figuring out what''s wrong?'),
(128, 3, 'Have you done any automation? Can you describe something?', 'Medium', '[Mercury interview] Have you done any automation? Can you describe something?'),
(129, 3, 'What level of Terraform and Kubernetes did you go to? Did you set up the Terraform configuration and do the applies? What level of Kubes do you have?', 'Hard', '[Westpac interview] What level of Terraform and Kubernetes did you go to? Did you set up the Terraform configuration and do the applies? What level of Kubes do you have?'),
(130, 4, 'Say I''ve got two systems that need to talk to each other — two endpoints, both part of a single function. How would you approach that? Not actually building it — how would you design it out?', 'Hard', '[One NZ interview] Say I''ve got two systems that need to talk to each other — two endpoints, both part of a single function. How would you approach that? Not actually building it — how would you design it out?'),
(131, 4, 'You own an application. The tech team is patching servers at 8pm and you need to gracefully stop your application — but another application is using the same resources and you''re blocked. How do you proceed?', 'Hard', '[Mercury interview] You own an application. The tech team is patching servers at 8pm and you need to gracefully stop your application — but another application is using the same resources and you''re blocked. How do you proceed?'),
(132, 4, 'What belongs in a business continuity plan? Give me the main topics that need to be addressed.', 'Hard', '[Mercury interview] What belongs in a business continuity plan? Give me the main topics that need to be addressed.'),
(133, 4, 'It''s two o''clock in the morning and a critical platform has stopped processing transactions. What do you do in the first 30 minutes?', 'Hard', '[Mercury interview] It''s two o''clock in the morning and a critical platform has stopped processing transactions. What do you do in the first 30 minutes?');
INSERT INTO "FollowUpQuestions" ("QuestionId", "Text") VALUES
(71, 'Is there any space that we can negotiate in the future?'),
(74, 'Is that a paid role as well?'),
(74, 'How does that play out if you came full time here?'),
(91, 'kind of like when you took on a new task or responsibility that was outside of your skill set in order to grow'),
(96, 'Say you''ve got five different asks from five different people — would you write it down on a bit of paper? What''s your style?'),
(97, 'They''re both the same kind of build — one serves customer group A, the other group B. Which one do you build?'),
(100, 'Did your teammate in the end accept your point of view? What was the outcome?'),
(101, 'How did you feel at the time? Can you elaborate on your thinking?'),
(104, 'What if the documentation has nothing? After your senior shares some thoughts, how do you follow up?'),
(106, 'What were the learnings? Did you document it? Was it implemented in future development or maintenance?'),
(108, 'Would that be different from troubleshooting a product in your own team?'),
(110, 'What happens if you recurse too deep?'),
(110, 'Why is stack allocation faster?'),
(110, 'In C#, is a struct always on the stack?'),
(113, 'Would you install Python on your PC yourself? Have you done it before?'),
(119, 'What about just the AI bot itself? What metrics of the agent would you observe?'),
(125, 'In terms of the actual monitoring — say it''s Datadog, how would you do it differently?'),
(125, 'Will you do it for both or only business critical?'),
(125, 'So you won''t monitor at the same frequency?'),
(126, 'Do you have experience with CloudFormation and the alerting inside AWS?'),
(126, 'You mentioned using both Datadog and Grafana — why two platforms?'),
(128, 'Do those scripts run manually, or how do they run?'),
(131, 'Let''s say this is on-prem and you don''t have a blue-green arrangement.'),
(132, 'Imagine a new application you get to set up — how would you plan it so the business keeps running if one site fails?');
